# WAR ARENA - Trending Cache (arena top-battles view, lazy 4h refresh) - Installer
# Serves GET /trending from a cached snapshot; refreshes at most once per TTL.
# Address source is swappable; default = configurable seed list (honest, no invented feed).
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-trending.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Trending cache installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/product/trending/trendingCache.ts" ""
Write-B64 "src/integration/warRuntime.ts" ""
Write-B64 "src/api/wiredApp.ts" ""
Write-B64 "src/deploy/env.ts" ""
Write-B64 "src/deploy/server.ts" ""
Write-B64 "tests/unit/trendingCache.test.ts" ""
Write-B64 "tests/integration/wiredApi.test.ts" ""

Write-Host ""; Write-Host "Verifying ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Trending cache installed. Expected: 1034 passed + 1 skipped, 482 guards." -ForegroundColor Green
Write-Host "Set TRENDING_SEED=sol:ADDR,bsc:ADDR and TRENDING_TTL_HOURS=4 in env when deploying." -ForegroundColor Yellow
